with with_windows as (select *, last_value(quantity) ignore nulls over (partition by product_id order by quantity, id rows between unbounded preceding and current row) last_known_quantity, lead(quantity, 1) over w_part next_quantity, sum(quantity) over (partition by store_id order by quantity, id rows between unbounded preceding and current row) running_quantity, rank() over (order by quantity) quantity_rank from inventory where product_id in (3, 4) window w_part as (order by quantity, id)) select s.id, s.store_id, s.quantity, s.last_known_quantity, s.running_quantity, s.quantity_rank, (select min(t2.revenue) from store_sales t2 where t2.store_id = s.store_id) as min_store_sale_revenue from with_windows s;
